import{_ as e,o as d,c as a,a2 as i}from"./chunks/framework.mRCPFc5l.js";const u=JSON.parse('{"title":"Tiles and cards","description":"Maintain content for tabs of type TilesGrid and CardList — including action types.","frontmatter":{"title":"Tiles and cards","description":"Maintain content for tabs of type TilesGrid and CardList — including action types."},"headers":[],"relativePath":"en/apptiveteams/kacheln-und-karten.md","filePath":"en/apptiveteams/kacheln-und-karten.md","lastUpdated":1787319236000}'),o={name:"en/apptiveteams/kacheln-und-karten.md"};function r(n,t,s,l,c,h){return d(),a("div",null,[...t[0]||(t[0]=[i('<h1 id="tiles-and-cards" tabindex="-1">Tiles and cards <a class="header-anchor" href="#tiles-and-cards" aria-label="Permalink to &quot;Tiles and cards&quot;">​</a></h1><p>Tabs of type <code>TilesGrid</code> and <code>CardList</code> pull their content from the Grid linked in the tab via <code>gridUri</code>. Every row of that Grid becomes a tile or a card.</p><h2 id="tile-view-tilesgrid" tabindex="-1">Tile view <code>TilesGrid</code> <a class="header-anchor" href="#tile-view-tilesgrid" aria-label="Permalink to &quot;Tile view `TilesGrid`&quot;">​</a></h2><p>A grid of tiles — the typical home screen with quick access to forms and links.</p><table tabindex="0"><thead><tr><th>Field Key</th><th>Field type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>title</code></td><td>Text</td><td>yes</td><td>Label of the tile</td></tr><tr><td><code>icon</code></td><td>Files (SVG)</td><td>yes</td><td>Icon of the tile, single-color SVG</td></tr><tr><td><code>uri</code></td><td>Weblink</td><td>yes</td><td>Target of the tile, e.g. a form link</td></tr><tr><td><code>actionType</code></td><td>Text / Single Select</td><td>yes</td><td>How the target is opened — see below</td></tr></tbody></table><h2 id="card-view-cardlist" tabindex="-1">Card view <code>CardList</code> <a class="header-anchor" href="#card-view-cardlist" aria-label="Permalink to &quot;Card view `CardList`&quot;">​</a></h2><p>A list of cards with image, headline, and action button — for news, announcements, or tasks.</p><table tabindex="0"><thead><tr><th>Field Key</th><th>Field type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>headline</code></td><td>Text</td><td>yes</td><td>Headline of the card</td></tr><tr><td><code>supportingText</code></td><td>Text</td><td>no</td><td>Description text under the headline</td></tr><tr><td><code>image</code></td><td>Files (Image)</td><td>no</td><td>Image on the card</td></tr><tr><td><code>actionUri</code></td><td>Weblink</td><td>yes</td><td>Target of the action button</td></tr><tr><td><code>actionType</code></td><td>Text / Single Select</td><td>yes</td><td>How the target is opened — see below</td></tr><tr><td><code>actionLabel</code></td><td>Text</td><td>no</td><td>Label of the action button</td></tr><tr><td><code>createdAt</code></td><td>Date and time</td><td>yes</td><td>Shown on the card, e.g. as &quot;Today&quot; or &quot;Yesterday&quot;</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">Have <code>createdAt</code> fill in automatically</p><p>Set the field up as the <strong>Created at</strong> column type. It&#39;s then set automatically for every new entry — including entries created through a form or a Flow. → <a href="/en/referenz/spaltentypen">Column types</a></p></div><h2 id="action-types" tabindex="-1">Action types <a class="header-anchor" href="#action-types" aria-label="Permalink to &quot;Action types&quot;">​</a></h2><p>The value in <code>actionType</code> determines how the target is opened.</p><table tabindex="0"><thead><tr><th>Value</th><th>Behavior</th><th>Tiles</th><th>Cards</th></tr></thead><tbody><tr><td><code>formLink</code></td><td>Opens an ApptiveGrid form directly in the app</td><td>✓</td><td>✓</td></tr><tr><td><code>internalLink</code></td><td>Opens the page inside the app</td><td>✓</td><td>✓</td></tr><tr><td><code>externalLink</code></td><td>Opens the page in the device&#39;s browser</td><td>✓</td><td>✓</td></tr><tr><td><code>triggerFlow</code></td><td>Opens the target in an in-app browser</td><td>–</td><td>✓</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title"><code>internalLink</code> passes along who&#39;s signed in</p><p>For ApptiveGrid links, <code>internalLink</code> also passes along the signed-in person. A form filled out through it then carries the correct person in the <strong>Created by</strong> field, instead of &quot;Form link.&quot;</p><p>If you need to trace who submitted a report, that&#39;s the crucial difference from <code>externalLink</code>.</p></div><p><code>triggerFlow</code> only exists for cards. It lets you kick off an ApptiveGrid Flow directly from a card. → <a href="/en/flows/webhook-trigger">Trigger a Flow via webhook</a></p><h2 id="rows-with-gaps-are-skipped" tabindex="-1">Rows with gaps are skipped <a class="header-anchor" href="#rows-with-gaps-are-skipped" aria-label="Permalink to &quot;Rows with gaps are skipped&quot;">​</a></h2><p>As with tabs: if a required field is missing, the tile or card doesn&#39;t appear — without any message. If a tile is unexpectedly missing, check the required fields first, then the spelling of the field Keys.</p><div class="tip custom-block"><p class="custom-block-title">Control order via a sorted View</p><p>Tiles and cards appear in the order of the linked Grid. Link a <strong>View</strong> instead of the Grid, and you control order and visibility through its sorting and filters — for news, for example, sorted descending by date.</p><p>→ <a href="/en/ansichten/filtern-sortieren-gruppieren">Filtering, sorting, and grouping</a></p></div><h2 id="next" tabindex="-1">Next <a class="header-anchor" href="#next" aria-label="Permalink to &quot;Next&quot;">​</a></h2><ul><li><a href="/en/apptiveteams/tabs">Setting up tabs</a></li><li><a href="/en/apptiveteams/einstellungen">Add to the settings screen</a></li><li><a href="/en/apptiveteams/fehlerbehebung">Tips and troubleshooting</a></li></ul>',19)])])}const f=e(o,[["render",r]]);export{u as __pageData,f as default};
